# Left region (cols 0-13): left speaker from TL(0,0) and BL(14,0)
# Right region (cols 14-15): right speaker from BR(14,15) and TR
#
# For left region:
#   Even rows (including 0): color (2 or 4) at columns with same parity as row value
#   Odd rows: color (2 or 4) at columns with different parity from row value
#   For row 14, BL value (4) applies
#   For row 0, TL value (2) applies
#
# For right region (cols 14-15):
# Right speaker rule: color when parities differ, BG when same
#   But BR value 7 applies throughout

def make_test_output():
    H, W = 15, 16
    TL, BL = 2, 4
    TR, BR = 6, 7  # TR at (0,15), BR at (14,15)
    BG = 6

    output = [[BG for _ in range(W)] for _ in range(H)]

    for r in range(H):
        for c in range(W):
            # Left region: cols 0-13
            if c <= 13:
                if r % 2 == 0:
                    # Left speaker (TL)
                    if c % 2 == 0:
                        output[r][c] = TL
                    else:
                        output[r][c] = BG
                else:
                    # Left speaker (BL)
                    if c % 2 == 1:
                        output[r][c] = BL
                    else:
                        output[r][c] = BG
            # Right region: cols 14-15
            else:
                if (r % 2) == (c % 2):
                    output[r][c] = BG
                else:
                    output[r][c] = BR

    return output

